        <p><strong>Name:</strong> {profile.value.name}</p>
        <p><strong>Email:</strong> {profile.value.email}</p>
        <p><strong>Role:</strong> {profile.value.role}</p>
      </div>
      <p style={{ marginTop: "20px" }}>
        <a href="/" style={{ color: "blue", textDecoration: "underline" }}>Go back home</a>
      </p>
    </div>
  );
});

import { component$ } from "@builder.io/qwik";
import { routeLoader$, routeAction$, Form } from "@builder.io/qwik-city";
import { getUserByEmail, getAllUsers, updateUserRole } from "../../../db";

export const useAdminUsersLoader = routeLoader$(({ cookie, redirect, status }) => {
  const sessionEmail = cookie.get("session_email")?.value;
  if (!sessionEmail) {
    throw redirect(302, "/unauthorized");
  }

  const user = getUserByEmail(sessionEmail);
  if (!user || user.role !== "ADMIN") {
    throw redirect(302, "/unauthorized");
  }

  status(200);
  return getAllUsers();
});

export const useUpdateRoleAction = routeAction$((data, { cookie, status }) => {
  const sessionEmail = cookie.get("session_email")?.value;
  if (!sessionEmail) {
    status(403);
    return { success: false, error: "Unauthenticated" };
  }

  const performingUser = getUserByEmail(sessionEmail);
  if (!performingUser || performingUser.role !== "ADMIN") {
    status(403);
    return { success: false, error: "Unauthorized" };
  }

  const targetEmail = data.email as string;
  const targetRole = data.role as string;

  if (!targetEmail || !targetRole) {
    status(400);
    return { success: false, error: "Missing required fields" };
  }

  if (targetRole !== "ADMIN" && targetRole !== "USER") {
    status(400);
    return { success: false, error: "Invalid role" };
  }

  const updated = updateUserRole(targetEmail, targetRole);
  if (!updated) {
    status(404);
    return { success: false, error: "User not found" };
  }

  return { success: true };
});

export default component$(() => {
  const users = useAdminUsersLoader();
  const updateRoleAction = useUpdateRoleAction();

  return (
    <div style={{ padding: "20px", fontFamily: "sans-serif" }}>
      <h1>Admin - User Management</h1>

      {updateRoleAction.value?.success && (
        <div style={{ padding: "10px", backgroundColor: "#e6ffe6", border: "1px solid green", borderRadius: "5px", marginBottom: "15px", color: "green" }}>
          Role updated successfully!
        </div>
      )}

      {updateRoleAction.value?.error && (
        <div style={{ padding: "10px", backgroundColor: "#ffe6e6", border: "1px solid red", borderRadius: "5px", marginBottom: "15px", color: "red" }}>
          Error: {updateRoleAction.value.error}
        </div>
      )}

      <table style={{ width: "100%", borderCollapse: "collapse", marginTop: "10px" }}>
        <thead>
          <tr style={{ backgroundColor: "#f2f2f2", textAlign: "left" }}>
            <th style={{ padding: "10px", border: "1px solid #ddd" }}>ID</th>
            <th style={{ padding: "10px", border: "1px solid #ddd" }}>Name</th>
            <th style={{ padding: "10px", border: "1px solid #ddd" }}>Email</th>
            <th style={{ padding: "10px", border: "1px solid #ddd" }}>Current Role</th>
            <th style={{ padding: "10px", border: "1px solid #ddd" }}>Update Role</th>
          </tr>
        </thead>
        <tbody>
          {users.value.map((user) => (
            <tr key={user.id}>
              <td style={{ padding: "10px", border: "1px solid #ddd" }}>{user.id}</td>
              <td style={{ padding: "10px", border: "1px solid #ddd" }}>{user.name}</td>
              <td style={{ padding: "10px", border: "1px solid #ddd" }}>{user.email}</td>
              <td style={{ padding: "10px", border: "1px solid #ddd" }}>
                <span style={{
                  padding: "3px 8px",
                  borderRadius: "3px",
                  fontSize: "12px",
                  fontWeight: "bold",
                  backgroundColor: user.role === "ADMIN" ? "#ffe6cc" : "#e6f2ff",
                  color: user.role === "ADMIN" ? "#cc6600" : "#0066cc"
                }}>
                  {user.role}
                </span>
              </td>
              <td style={{ padding: "10px", border: "1px solid #ddd" }}>
                <Form action={updateRoleAction} style={{ display: "flex", gap: "10px", alignItems: "center" }}>
                  <input type="hidden" name="email" value={user.email} />
                  <select name="role" style={{ padding: "5px", borderRadius: "3px" }}>
                    <option value="USER" selected={user.role === "USER"}>USER</option>
                    <option value="ADMIN" selected={user.role === "ADMIN"}>ADMIN</option>
                  </select>
                  <button type="submit" style={{ padding: "5px 10px", backgroundColor: "#0066cc", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}>
                    Update
                  </button>
                </Form>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <p style={{ marginTop: "20px" }}>
        <a href="/" style={{ color: "blue", textDecoration: "underline" }}>Go back home</a>
      </p>
    </div>
  );
});

import { component$ } from "@builder.io/qwik";
import { routeLoader$, routeAction$, Form, type DocumentHead } from "@builder.io/qwik-city";
import { getUserByEmail } from "../db";

export const useSessionLoader = routeLoader$(({ cookie }) => {
  const sessionEmail = cookie.get("session_email")?.value;
  if (!sessionEmail) {
    return { loggedIn: false };
  }

  const user = getUserByEmail(sessionEmail);
  if (!user) {
    return { loggedIn: false };
  }

  return {
    loggedIn: true,
    user,
  };
});

export const useSessionAction = routeAction$((data, { cookie }) => {
  const action = data.action as string;
  if (action === "login") {
    const email = data.email as string;
    if (email) {
      cookie.set("session_email", email, { path: "/", httpOnly: true, sameSite: "strict" });
    }
  } else if (action === "logout") {
    cookie.delete("session_email", { path: "/" });
  }
});

export default component$(() => {
  const session = useSessionLoader();
  const sessionAction = useSessionAction();

  return (
    <div style={{ padding: "20px", fontFamily: "sans-serif", maxWidth: "600px" }}>
      <h1>Qwik SQLite RBAC System</h1>

      <div style={{ border: "1px solid #ccc", padding: "15px", borderRadius: "5px", marginBottom: "20px" }}>
        <h3>Current Authentication Status</h3>
        {session.value.loggedIn && session.value.user ? (
          <div>
            <p>Logged in as: <strong>{session.value.user.name}</strong> ({session.value.user.email})</p>
            <p>Role: <strong style={{ color: session.value.user.role === "ADMIN" ? "red" : "green" }}>{session.value.user.role}</strong></p>

            <Form action={sessionAction}>
              <input type="hidden" name="action" value="logout" />
              <button type="submit" style={{ padding: "8px 15px", backgroundColor: "#ff4d4d", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}>
                Log Out
              </button>
            </Form>
          </div>
        ) : (
          <div>
            <p>Status: <strong>Unauthenticated</strong></p>
            <p>Select a user to log in:</p>
            <div style={{ display: "flex", gap: "10px" }}>
              <Form action={sessionAction}>
                <input type="hidden" name="action" value="login" />
                <input type="hidden" name="email" value="admin@example.com" />
                <button type="submit" style={{ padding: "8px 15px", backgroundColor: "#4caf50", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}>
                  Log In as Admin
                </button>
              </Form>

              <Form action={sessionAction}>
                <input type="hidden" name="action" value="login" />
                <input type="hidden" name="email" value="user@example.com" />
                <button type="submit" style={{ padding: "8px 15px", backgroundColor: "#2196f3", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}>
                  Log In as Regular User
                </button>
              </Form>
            </div>
          </div>
        )}
      </div>

      <div style={{ border: "1px solid #ccc", padding: "15px", borderRadius: "5px" }}>
        <h3>Navigation & Authorization Testing</h3>
        <ul style={{ paddingLeft: "20px", lineHeight: "2" }}>
          <li>
            <a href="/profile" style={{ color: "blue", textDecoration: "underline" }}>
              /profile
            </a>{" "}
            (Accessible to <strong>ADMIN</strong> and <strong>USER</strong>)
          </li>
          <li>
            <a href="/admin/users" style={{ color: "blue", textDecoration: "underline" }}>
              /admin/users
            </a>{" "}
            (Accessible only to <strong>ADMIN</strong>)
          </li>
          <li>
            <a href="/unauthorized" style={{ color: "blue", textDecoration: "underline" }}>
              /unauthorized
            </a>{" "}
            (Accessible to everyone)
          </li>
        </ul>
      </div>
    </div>
  );
});

