      }

      if (overlay) {
        overlay.remove();
        visibleNodes.delete(node);
      }
    }

    async function updateImg(node) {
      const overlay = visibleNodes.get(node);
      if (!node.isConnected) {
        if (overlay) {
          overlay.remove();
